"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[4269],{7742(a,n,i){i.r(n),i.d(n,{assets:()=>k,contentTitle:()=>r,default:()=>d,frontMatter:()=>u,metadata:()=>e,toc:()=>m});const e=JSON.parse('{"id":"learning/courses/quantum-computing-in-practice/applications-of-qc","title":"Masalah apa yang cocok untuk komputer kuantum?","description":"Baca tentang bagaimana kita menentukan jenis masalah yang mungkin mendapat manfaat dari solusi kuantum, dan lihat beberapa contoh terbaru dari komunitas.","source":"@site/i18n/id/docusaurus-plugin-content-docs/current/learning/courses/quantum-computing-in-practice/applications-of-qc.mdx","sourceDirName":"learning/courses/quantum-computing-in-practice","slug":"/learning/courses/quantum-computing-in-practice/applications-of-qc","permalink":"/learning/courses/quantum-computing-in-practice/applications-of-qc","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/quantum-computing-in-practice/applications-of-qc.mdx","tags":[],"version":"current","frontMatter":{"title":"Masalah apa yang cocok untuk komputer kuantum?","sidebar_label":"Masalah apa yang cocok untuk komputer kuantum?","description":"Baca tentang bagaimana kita menentukan jenis masalah yang mungkin mendapat manfaat dari solusi kuantum, dan lihat beberapa contoh terbaru dari komunitas.","notebook_path":"learning/courses/quantum-computing-in-practice/applications-of-qc.ipynb"},"sidebar":"tutorialsSidebar","previous":{"title":"QAOA skala utilitas","permalink":"/learning/courses/quantum-computing-in-practice/utility-scale-qaoa"},"next":{"title":"Pemetaan","permalink":"/learning/courses/quantum-computing-in-practice/mapping"}}');var t=i(74848),s=i(28453);const u={title:"Masalah apa yang cocok untuk komputer kuantum?",sidebar_label:"Masalah apa yang cocok untuk komputer kuantum?",description:"Baca tentang bagaimana kita menentukan jenis masalah yang mungkin mendapat manfaat dari solusi kuantum, dan lihat beberapa contoh terbaru dari komunitas.",notebook_path:"learning/courses/quantum-computing-in-practice/applications-of-qc.ipynb"},r=void 0,k={},m=[{value:"Pendahuluan",id:"introduction",level:2},{value:"Kesulitan klasik vs. kuantum",id:"classical-vs-quantum-difficulty",level:2},{value:"Kelas kompleksitas",id:"complexity-classes",level:3},{value:"Komputer kuantum saat ini dan batasannya",id:"todays-quantum-computers-and-their-limits",level:3},{value:"Area Aplikasi dan Kasus Penggunaan",id:"application-areas-and-use-cases",level:2},{value:"Kasus Penggunaan 1: Mensimulasikan dinamika hadron",id:"use-case-1-simulating-hadron-dynamics",level:3},{value:"Kasus Penggunaan 2: Optimasi Ising spin-glass",id:"use-case-2-optimization-of-an-ising-spin-glass",level:3},{value:"Kasus Penggunaan 3: Prediksi struktur sekunder mRNA",id:"use-case-3-mrna-secondary-structure-prediction",level:3},{value:"Kesimpulan",id:"conclusion",level:2}];function l(a){const n={a:"a",annotation:"annotation",h2:"h2",h3:"h3",img:"img",li:"li",math:"math",mi:"mi",mn:"mn",mo:"mo",mrow:"mrow",ol:"ol",p:"p",semantics:"semantics",span:"span",ul:"ul",...(0,s.R)(),...a.components},{IBMVideo:e}=n;return e||function(a,n){throw new Error("Expected "+(n?"component":"object")+" `"+a+"` to be defined: you likely forgot to import, pass, or provide it.")}("IBMVideo",!0),(0,t.jsxs)(t.Fragment,{children:["\n","\n",(0,t.jsxs)(n.p,{children:["Tonton video tentang aplikasi komputasi kuantum dari Olivia Lanes, atau buka video di jendela terpisah di ",(0,t.jsx)(n.a,{href:"https://youtu.be/33QmsXhIlpU",children:"YouTube."})]}),"\n",(0,t.jsx)(e,{id:"134063426",title:"Dalam video ini, Olivia Lanes mendeskripsikan beberapa kemungkinan aplikasi komputasi kuantum pada skala utilitas. Ini termasuk simulasi hadron dan spin glass, serta pemodelan struktur protein."}),"\n",(0,t.jsx)(n.h2,{id:"introduction",children:"Pendahuluan"}),"\n",(0,t.jsx)(n.p,{children:"Dalam pelajaran sebelumnya, kita membahas satu masalah secara mendalam \u2013 memecahkan masalah optimasi Max-Cut menggunakan formulasi QUBO. Hari ini kita akan mengambil pendekatan berbeda dan membahas aplikasi jangka dekat secara lebih luas. Kita akan mulai dengan memberikan gambaran tentang bagaimana kita menentukan jenis masalah yang mungkin mendapat manfaat dari solusi kuantum. Kemudian, kita akan melihat beberapa contoh terbaru pekerjaan yang dilakukan di komunitas kita. Ini akan membantu kamu mulai mengembangkan intuisi untuk berbagai jenis masalah komputasi kuantum dan bagaimana kita mendekatinya."}),"\n",(0,t.jsx)(n.h2,{id:"classical-vs-quantum-difficulty",children:"Kesulitan klasik vs. kuantum"}),"\n",(0,t.jsx)(n.p,{children:"Sebelum masuk ke contoh, mari kita bahas dulu bagaimana kita mempelajari dan mengkategorikan tingkat kesulitan berbagai masalah. Beberapa masalah bisa diselesaikan dengan mudah di komputer klasik, dan kita tidak butuh komputer kuantum untuk menyelesaikannya. Di sisi lain, ada masalah yang sangat sulit di mana komputer kuantum diperlukan untuk menyelesaikannya. Satu contoh terkenal adalah mencari faktor prima dari bilangan bulat yang sangat besar. Enkripsi RSA bergantung pada kesulitan masalah ini, dan algoritma Shor dirancang untuk menyelesaikannya di komputer kuantum. Contoh lain adalah menemukan solusi dalam kumpulan data yang tidak terurut \u2013 ini secara teoritis bisa diselesaikan oleh algoritma kuantum yang dikenal sebagai algoritma Grover. Namun, sebagian besar ahli setuju bahwa jenis algoritma ini akan memerlukan implementasi koreksi kesalahan dan teknologinya belum siap."}),"\n",(0,t.jsx)(n.p,{children:"Jadi, kita mencari masalah yang bisa kita tangani di suatu titik manis antara yang sangat mudah dan sangat sulit \u2013 yang bisa ditangani oleh komputer kuantum saat ini, tetapi komputer klasik kesulitan."}),"\n",(0,t.jsx)(n.h3,{id:"complexity-classes",children:"Kelas kompleksitas"}),"\n",(0,t.jsx)(n.p,{children:"Kesulitan masalah-masalah ini dikategorikan dan dianalisis dalam cabang ilmu komputer yang disebut teori kompleksitas komputasi. Ada banyak kelas kompleksitas berbeda dalam komputasi klasik, tetapi beberapa yang paling fundamental adalah:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"P: Masalah yang bisa diselesaikan dalam waktu polinomial seiring skala masalah meningkat. Mudah untuk diselesaikan."}),"\n",(0,t.jsx)(n.li,{children:"NP: Ini singkatan dari nondeterministic polynomial. Masalah-masalah ini tidak selalu bisa diselesaikan dalam waktu polinomial, tetapi jawabannya bisa diverifikasi dalam waktu polinomial."}),"\n",(0,t.jsx)(n.li,{children:"NP-complete adalah masalah paling sulit dalam NP dan tidak memiliki solusi polinomial yang diketahui. Di sinilah masalah terkenal seperti traveling salesman dan permainan Sudoku berada."}),"\n",(0,t.jsx)(n.li,{children:"BPP, atau bounded-error polynomial problems, yang bisa diselesaikan dalam batas kesalahan tertentu oleh komputer klasik probabilistik dalam waktu polinomial."}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"Ketika konsep komputasi kuantum ditemukan, orang menghabiskan banyak upaya untuk mencari tahu kelas masalah apa yang bisa diselesaikan secara efisien oleh jenis komputer baru ini. Kelas masalah baru ditemukan:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"BQP, atau bounded-error quantum polynomial problems. Ini adalah setara kuantum dari BPP: Ini adalah kelas masalah keputusan yang bisa diselesaikan oleh komputer kuantum dalam waktu polinomial dengan kemungkinan kesalahan kecil."}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.img,{alt:"Hubungan yang diduga di antara kelas kompleksitas",src:i(52600).A+"",width:"976",height:"682"})}),"\n",(0,t.jsx)(n.p,{children:"Semua kelas ini berada dalam kelas yang lebih besar yang kita sebut PSPACE. Di atas adalah diagram hubungan yang diduga di antara beberapa kelas kompleksitas, tetapi ini sangat sulit dibuktikan secara matematis. Kamu akan melihat bahwa BQP tidak selalu tumpang tindih dengan NP-complete. Tapi mungkin kamu masih pernah melihat beberapa pendekatan komputasi kuantum yang bertujuan mencoba menyelesaikan masalah di NP-complete."}),"\n",(0,t.jsx)(n.p,{children:"Satu kesalahpahaman umum adalah bahwa tidak ada gunanya mengeksplorasi solusi kuantum untuk masalah apa pun di mana bukti matematis tentang percepatan kuantum belum ditemukan. Tapi bukti matematis bahwa algoritma kuantum lebih cepat dari padanannya yang klasik sulit ditemukan. Shor dan Grover adalah dua dari hanya segelintir contoh di mana ini telah dilakukan sejauh ini. Bahkan, membuktikan secara ketat bahwa P dan NP berbeda adalah salah satu pertanyaan terbuka paling terkenal di seluruh matematika, meskipun semua intuisi memberitahu kita bahwa mereka pasti berbeda."}),"\n",(0,t.jsx)(n.p,{children:"Tapi cara suatu algoritma berkembang dengan ukuran masalah yang meningkat \u2013 yang tercermin dalam kelas kompleksitas \u2013 tidak selalu merupakan fitur algoritma yang paling relevan. Penskalaan ini sering merupakan skenario kasus terburuk. Sangat mungkin bahwa, dalam praktiknya, skenario kasus terburuk bukan yang paling sering kita temui."}),"\n",(0,t.jsx)(n.p,{children:"Hanya karena bukti kekerasan sulit tidak berarti kita tidak bisa membuat kemajuan. Kita memperkenalkan ide solusi heuristik. Jika kamu seorang eksperimentalis, kamu kemungkinan mengenal dan menyukai jenis solusi ini. Heuristik adalah pendekatan apa pun untuk memecahkan masalah yang pragmatis, tetapi tidak selalu optimal, karena solusi tidak perlu optimal untuk berguna. Misalnya, pikirkan tentang aplikasi keuangan. Kita belum menemukan percepatan eksponensial untuk sebagian besar algoritma keuangan yang bisa digunakan kuantum, tetapi kita tidak perlu solusi yang optimal. Dalam keuangan, bahkan solusi yang hanya 0,1% lebih efisien bisa menghasilkan miliaran dolar keuntungan."}),"\n",(0,t.jsx)(n.h3,{id:"todays-quantum-computers-and-their-limits",children:"Komputer kuantum saat ini dan batasannya"}),"\n",(0,t.jsx)(n.p,{children:"Jadi, bagaimana kita tahu kasus penggunaan dan masalah apa yang cocok untuk komputasi kuantum saat ini? Apakah ada alasan bagus untuk percaya bahwa utilitas kuantum, atau bahkan keunggulan, bisa ditemukan sekarang atau dalam waktu dekat?"}),"\n",(0,t.jsx)(n.p,{children:"Mungkin lebih mudah untuk pertama-tama menyebutkan hal-hal yang sebaiknya tidak ada dalam masalah tersebut. Tidak bisa memerlukan qubit dalam jumlah besar. Kita belum memiliki prosesor dengan ribuan hingga jutaan qubit yang tersedia. Itulah salah satu alasan utama mengapa algoritma Shor dan sejenisnya masih jauh dari terealisasi. Circuit-nya juga tidak boleh terlalu dalam. Batas kedalaman Circuit bergantung pada banyak faktor, tetapi secara umum, jika eksperimenmu memerlukan kedalaman yang belum pernah dicapai dalam literatur, kemungkinan tidak akan berhasil. Dan terakhir, jenis algoritma apa pun yang kita tahu akan memerlukan koreksi kesalahan belum bisa dilakukan."}),"\n",(0,t.jsxs)(n.p,{children:["Semua keterbatasan ini dibahas dalam ",(0,t.jsx)(n.a,{href:"https://www.ibm.com/quantum/technology#roadmap",children:"peta jalan IBM Quantum\xae"})," dan kita berharap bisa mencapai koreksi kesalahan pada awal 2030-an, tetapi untuk sekarang, kita perlu mencari eksperimen yang memanfaatkan sebagian besar qubit yang saat ini tersedia di QPU tertentu. Kita juga menekankan pentingnya mitigasi dan penekanan kesalahan. Dan terakhir, harus ada ekstensi yang jelas ke aplikasi masa depan yang akan penting bagi masyarakat dan yang pada akhirnya bisa mengarah pada keunggulan kuantum."]}),"\n",(0,t.jsx)(n.h2,{id:"application-areas-and-use-cases",children:"Area Aplikasi dan Kasus Penggunaan"}),"\n",(0,t.jsx)(n.p,{children:"Sekarang mari kita bahas beberapa contoh kasus penggunaan, yang termasuk dalam tiga kategori utama yang telah kami identifikasi sebagai yang paling mungkin menghasilkan hasil yang baik dalam jangka dekat hingga menengah:"}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:["Simulasi alam. Metode klasik komputasi simulasi atom dan molekul saat ini dibatasi oleh deskripsi matematis struktur atom yang tidak efisien. Menyimpan dan memanipulasi keadaan kuantum memerlukan sumber daya yang secara eksponensial lebih banyak di komputer klasik tetapi bisa dilakukan secara efisien di komputer kuantum. Ini bisa mengarah pada perkembangan dalam sekuestrasi karbon dioksida, baterai alternatif, atau penemuan obat baru. Beberapa algoritma yang sangat relevan di area ini adalah: Variational Quantum Eigensolver (VQE), yang digunakan untuk memperkirakan sifat tertentu dari suatu material, seperti keadaan ekuilibrium atau energi minimum; algoritma Time Dynamics Simulation (TDS), yang digunakan untuk memperkirakan fungsi respons atau sifat spektral material; dan pendatang baru, ",(0,t.jsx)(n.a,{href:"/learning/courses/quantum-diagonalization-algorithms/sqd-overview",children:"Sample-based Quantum Diagonalization (SQD)"}),", yang kita pikir akan banyak kita dengar di masa depan."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Optimasi. Area ini ada di mana-mana dalam komputasi, sehingga kasus penggunaannya sangat banyak dan bervariasi. Beberapa contoh yang sering kita dengar adalah optimasi portofolio dalam keuangan, desain industri, dan distribusi serta rantai pasokan. Algoritma yang paling umum yang akan kamu dengar terkait keuangan adalah yang sudah kita bahas secara mendalam: quantum approximate optimization algorithm, atau QAOA."}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Quantum machine learning. Area ini telah menghasilkan banyak kegembiraan dalam beberapa tahun terakhir, tetapi kemungkinan QML tidak akan berguna secepat simulasi. Namun ada beberapa algoritma yang mengesankan yang sedang dikerjakan untuk menangani beberapa kasus penggunaan yang sangat penting. Beberapa kasus penggunaan yang mungkin ini adalah pemrosesan bahasa alami, analisis lalu lintas jaringan, dan bahkan deteksi penipuan dalam transaksi keuangan. Algoritma yang relevan di area ini adalah quantum support vector machine (QSVM), quantum neural networks (QNN), dan quantum generative adversarial networks."}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"Dalam area aplikasi yang luas ini, komunitas melihat manfaat dalam kelompok-kelompok yang bekerja sama yang fokus pada topik yang lebih spesifik. IBM\xae memprakarsai inisiatif yang disebut Working Groups untuk membantu para kolaborator bertemu dan menciptakan sinergi yang produktif dalam empat area spesifik: layanan kesehatan dan ilmu kehidupan, material dan high-performance computing (HPC), fisika energi tinggi, dan optimasi. Dan baru-baru ini, kelompok kerja kelima tentang keberlanjutan dibentuk."}),"\n",(0,t.jsx)(n.p,{children:"Kita sekarang akan memperbesar beberapa masalah yang baru-baru ini ditangani oleh beberapa kelompok kerja ini. Tujuan utama di sini bukan untuk memahami setiap detail eksperimen \u2013 ini bisa mengintimidasi bahkan para ahli jika makalahnya sedikit di luar bidang keahlian mereka. Tujuannya hanya untuk membantu mengembangkan intuisi tentang jenis masalah yang cocok untuk komputer kuantum dan bagaimana menanganinya. Dan jika kamu tertarik, kami mendorong kamu untuk membaca makalah lengkapnya."}),"\n",(0,t.jsx)(n.h3,{id:"use-case-1-simulating-hadron-dynamics",children:"Kasus Penggunaan 1: Mensimulasikan dinamika hadron"}),"\n",(0,t.jsxs)(n.p,{children:["Pertama, kita akan mempelajari makalah oleh kelompok Martin Savage di University of Washington yang berjudul ",(0,t.jsx)(n.a,{href:"https://journals.aps.org/prd/abstract/10.1103/PhysRevD.109.114510",children:"Quantum Simulations of Hadron Dynamics in the Schwinger Model Using 112 Qubits"}),"."]}),"\n",(0,t.jsx)(n.p,{children:'Jika kamu bukan fisikawan energi tinggi, kamu mungkin masih familiar dengan istilah "hadron," seperti dalam Large Hadron Collider (LHC), yang merupakan akselerator partikel raksasa berdiameter 27 km yang memungkinkan observasi boson Higgs untuk pertama kalinya. Hadron adalah partikel komposit subatomik yang terdiri dari partikel-partikel kecil lain yang disebut quark. Beberapa contoh hadron adalah neutron dan proton.'}),"\n",(0,t.jsx)(n.p,{children:"Untuk sedikit konteks, LHC dibangun untuk memungkinkan studi fisika fundamental dengan menumbuk partikel pada energi sangat tinggi. Dengan LHC, para ilmuwan berharap bisa belajar lebih banyak tentang alam semesta awal dan hukum fundamental alam. Pada prinsipnya, interaksi partikel-partikel ini bisa disimulasikan dari awal hingga akhir dengan komputer kuantum yang cukup kuat. Kita belum sampai di sana, tetapi kita terus membuat kemajuan."}),"\n",(0,t.jsx)(n.p,{children:"Model Schwinger adalah model sederhana yang populer digunakan untuk mensimulasikan beberapa dinamika ini. Ini adalah model yang mendeskripsikan perilaku elektron dan positron yang berinteraksi melalui foton dalam 1+1D, yang berarti waktu dan satu dimensi spasial. Model ini memiliki banyak kesamaan dengan quantum chromodynamics (QCD), yang mendeskripsikan bagaimana quark dan hadron berinteraksi, tetapi QCD sangat sulit untuk disimulasikan. Jadi, model Schwinger sering digunakan sebagai model toy untuk menyelidiki beberapa fenomena yang umum bagi keduanya."}),"\n",(0,t.jsx)(n.p,{children:"Untuk memahami mengapa mereka menangani masalah ini, mari kita ajukan serangkaian pertanyaan."}),"\n",(0,t.jsx)(n.p,{children:"Pertama, mengapa mereka punya alasan untuk percaya bahwa mensimulasikan ini di komputer kuantum akan berhasil? Dalam kasus ini, elektron dan positron dalam model Schwinger memiliki efek screening, menyebabkan korelasi antara fermion yang jauh untuk meluruh secara eksponensial dengan jarak. Ini berarti tidak ada begitu banyak interaksi jarak jauh yang diperlukan dari qubit di satu sisi chip ke yang lain, yang kita tahu sangat rentan kesalahan. Jadi, ini sangat bagus untuk perangkat keras yang kita miliki saat ini."}),"\n",(0,t.jsx)(n.p,{children:"Selanjutnya, mengapa topik ini menarik? Fisika energi tinggi secara umum sangat menarik. Orang-orang bersedia menghabiskan miliaran dolar untuk membangun LHC, dan ribuan ilmuwan dan teknisi di seluruh dunia telah mendedikasikan karier mereka di bidang ini. Meskipun model Schwinger bersifat sederhana dan tidak dirancang untuk mencakup tiga dimensi spasial, ini masih merupakan penyederhanaan yang berguna dari teori penuh."}),"\n",(0,t.jsx)(n.p,{children:"Terakhir, bagaimana pekerjaan ini dilakukan, atau bagaimana kita akan mendekati masalah jika kita ingin melanjutkan pekerjaan ini? Dalam eksperimen jenis simulasi, VQE adalah salah satu pendekatan yang paling umum, dan langkah pertamanya hampir selalu sama: siapkan ground state. Dalam kasus ini, itu adalah keadaan vakum. Dalam eksperimen ini, mereka menggunakan versi baru VQE yang disebut SC-ADAPT-VQE (yang merupakan singkatan dari Scalable Circuits - Adaptive Derivative-Assembled Pseudo-Trotter ansatz-VQE) untuk menyiapkan ground state dan paket gelombang hadron pada vakum ini. Langkah selanjutnya adalah membiarkan hadron berevolusi dalam waktu. Terakhir, identifikasi observable yang ingin kamu ukur dan ukurlah."}),"\n",(0,t.jsx)(n.p,{children:"Jika langkah-langkah itu terdengar sedikit familiar, minus bagian paket gelombang hadron, itu karena langkah-langkah ini sangat mirip dengan apa yang kita bahas dalam contoh QAOA di pelajaran sebelumnya. Kita mulai dari keadaan yang familiar (di sini keadaan vakum), dan kemudian kita biarkan berevolusi dalam waktu dengan serangkaian Hamiltonian yang dieksponensialkan. Banyak algoritma variasional mengikuti pendekatan umum ini. Perbedaan besar di sini, bagaimanapun, adalah bahwa kita membuat paket gelombang hadron yang dipusatkan dalam Circuit kita, sebelum kita mulai membiarkannya berevolusi."}),"\n",(0,t.jsx)(n.p,{children:"Jadi, bagaimana kita membuat paket gelombang? Pada vakum, hadron bisa dieksitasi dengan membuat pasangan fermion-antifermion pada situs yang berdekatan. Dengan menyiapkan superposisi hadron seperti itu di lokasi berbeda, paket gelombang yang sewenang-wenang bisa disiapkan. Para penulis memusatkan paket gelombang mereka di tengah Circuit untuk mengamati evolusi tanpa mencapai batas."}),"\n",(0,t.jsx)(n.p,{children:"Tapi ingat: nama permainannya saat bekerja dengan QPU yang berisik adalah menjaga kedalaman Circuit tetap bisa dikelola. Untuk melakukan ini, protokol SC-ADAPT-VQE menggunakan simetri dan hierarki dalam skala panjang untuk menentukan Circuit kuantum kedalaman rendah untuk persiapan keadaan. Ini akan menciptakan ansatz dengan jumlah parameter yang lebih kecil, dan karenanya, kedalaman yang lebih dangkal."}),"\n",(0,t.jsx)(n.p,{children:"Eksperimen dijalankan pada perangkat IBM Quantum Heron dan mencakup beberapa jenis mitigasi dan penekanan kesalahan yang berbeda: dynamical decoupling, zero noise extrapolation, Pauli twirling, dan teknik yang baru-baru ini dikembangkan yang disebut operator decoherence renormalization."}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.img,{alt:"Hasil simulasi hadron",src:i(77894).A+"",width:"1158",height:"838"})}),"\n",(0,t.jsx)(n.p,{children:"Di atas adalah gambar dari makalah yang menunjukkan observable yang diminati, kondensasi kiral, yang pada dasarnya adalah fase superfluida dari hadron. Sekarang, kita bisa melihat paket gelombang di pusat situs yang telah ditunjuk untuk menjalankan eksperimen ini. Garis hitam adalah hasil bebas kesalahan dari simulasi klasik (yang mahal secara komputasi), sementara titik-titik dengan bilah kesalahan adalah hasil dari komputer kuantum IBM 133 qubit, Torino."}),"\n",(0,t.jsxs)(n.p,{children:["Kita melihat dua langkah waktu berbeda dalam evolusi paket gelombang. Pada waktu ",(0,t.jsxs)(n.span,{className:"katex",children:[(0,t.jsx)(n.span,{className:"katex-mathml",children:(0,t.jsx)(n.math,{xmlns:"http://www.w3.org/1998/Math/MathML",children:(0,t.jsxs)(n.semantics,{children:[(0,t.jsxs)(n.mrow,{children:[(0,t.jsx)(n.mi,{children:"t"}),(0,t.jsx)(n.mo,{children:"="}),(0,t.jsx)(n.mn,{children:"1"})]}),(0,t.jsx)(n.annotation,{encoding:"application/x-tex",children:"t=1"})]})})}),(0,t.jsxs)(n.span,{className:"katex-html","aria-hidden":"true",children:[(0,t.jsxs)(n.span,{className:"base",children:[(0,t.jsx)(n.span,{className:"strut",style:{height:"0.6151em"}}),(0,t.jsx)(n.span,{className:"mord mathnormal",children:"t"}),(0,t.jsx)(n.span,{className:"mspace",style:{marginRight:"0.2778em"}}),(0,t.jsx)(n.span,{className:"mrel",children:"="}),(0,t.jsx)(n.span,{className:"mspace",style:{marginRight:"0.2778em"}})]}),(0,t.jsxs)(n.span,{className:"base",children:[(0,t.jsx)(n.span,{className:"strut",style:{height:"0.6444em"}}),(0,t.jsx)(n.span,{className:"mord",children:"1"})]})]})]}),", kamu bisa melihat bahwa kondensasi kiral sempit dan terlokalisasi, dan juga cocok dengan simulasi klasik dengan baik. Pada ",(0,t.jsxs)(n.span,{className:"katex",children:[(0,t.jsx)(n.span,{className:"katex-mathml",children:(0,t.jsx)(n.math,{xmlns:"http://www.w3.org/1998/Math/MathML",children:(0,t.jsxs)(n.semantics,{children:[(0,t.jsxs)(n.mrow,{children:[(0,t.jsx)(n.mi,{children:"t"}),(0,t.jsx)(n.mo,{children:"="}),(0,t.jsx)(n.mn,{children:"14"})]}),(0,t.jsx)(n.annotation,{encoding:"application/x-tex",children:"t=14"})]})})}),(0,t.jsxs)(n.span,{className:"katex-html","aria-hidden":"true",children:[(0,t.jsxs)(n.span,{className:"base",children:[(0,t.jsx)(n.span,{className:"strut",style:{height:"0.6151em"}}),(0,t.jsx)(n.span,{className:"mord mathnormal",children:"t"}),(0,t.jsx)(n.span,{className:"mspace",style:{marginRight:"0.2778em"}}),(0,t.jsx)(n.span,{className:"mrel",children:"="}),(0,t.jsx)(n.span,{className:"mspace",style:{marginRight:"0.2778em"}})]}),(0,t.jsxs)(n.span,{className:"base",children:[(0,t.jsx)(n.span,{className:"strut",style:{height:"0.6444em"}}),(0,t.jsx)(n.span,{className:"mord",children:"14"})]})]})]}),", lebih tersebar luas. Perbandingan dengan simulator tidak cukup sempurna sekarang, tetapi kamu masih bisa melihat persetujuan yang sangat baik antara teori dan data, yang mendorong."]}),"\n",(0,t.jsx)(n.p,{children:"Kesimpulannya, ini adalah contoh yang sangat keren dari jenis pekerjaan simulasi yang mungkin tidak awalnya kamu pikirkan untuk diterapkan pada komputasi kuantum, tetapi menunjukkan janji nyata. Ini tidak sempurna tetapi kamu tidak harus menjadi pakar fisika partikel untuk melihat bahwa komputer kuantum secara akurat memprediksi propagasi keluar dari paket gelombang, yang persis seperti yang kita harapkan. Semoga pekerjaan masa depan di area ini akan terus berlanjut dan fisikawan energi tinggi akan terus menemukan cara untuk memasukkan komputasi kuantum ke dalam alur kerja mereka. Tujuannya adalah memecahkan masalah teoritis yang sulit dengan lebih tepat dan menggunakan eksperimen untuk menerima atau menolak teori dengan harapan menemukan fisika baru, membangun detektor yang lebih baik, dan mengarah pada pemahaman alam yang lebih baik pada tingkat paling fundamentalnya."}),"\n",(0,t.jsx)(n.h3,{id:"use-case-2-optimization-of-an-ising-spin-glass",children:"Kasus Penggunaan 2: Optimasi Ising spin-glass"}),"\n",(0,t.jsxs)(n.p,{children:["Contoh berikutnya berfokus pada optimasi dan akan menjadi penelitian mendalam tentang makalah berjudul ",(0,t.jsx)(n.a,{href:"https://arxiv.org/abs/2405.13898",children:"Bias-Field Digitized Counterdiabatic Quantum Optimization"}),", yang dilakukan oleh anggota tim Kipu Quantum dan University of the Basque Country di Spanyol."]}),"\n",(0,t.jsx)(n.p,{children:'Dalam makalah tersebut, para penulis mengembangkan metode optimasi baru dan menerapkannya untuk menemukan ground state dari Ising spin-glass. Seperti yang kita bahas sebelumnya, banyak masalah optimasi kombinatorial bisa diformulasikan ulang sebagai penyelesaian untuk keadaan energi rendah dari Hamiltonian Ising. Model Ising mendeskripsikan interaksi dari susunan spin mikroskopis. Dalam beberapa rezim, model memprediksi bahwa spin berperilaku seperti gelas, di mana momen magnetis tidak teratur di atas apa yang disebut "suhu pembekuan."'}),"\n",(0,t.jsx)(n.p,{children:"Kita akan mulai seperti sebelumnya dengan serangkaian definisi. Yang pertama adalah counterdiabatic, yang merupakan jenis evolusi yang menekan efek non-adiabatik yang dialami oleh suatu sistem, terlepas dari seberapa cepat proses tersebut terjadi. Ingat teorema adiabatik dari episode terakhir \u2013 kamu biasanya perlu mengevolusi sistem sangat lambat jika kamu ingin tetap berada di ground state. Ini adalah masalah besar karena semakin lambat kita harus mengevolusi hal-hal, semakin banyak waktu yang kita miliki untuk kesalahan terjadi. Counterdiabatic driving (CD) bertujuan untuk melawan ini dengan menambahkan suku yang menangkal eksitasi yang tidak diinginkan ini. Ide utamanya adalah mempercepat seluruh eksperimen dan mengurangi kedalaman Circuit kuantum dengan menekan eksitasi yang bisa menyebabkan transisi palsu."}),"\n",(0,t.jsx)(n.p,{children:"Sekarang untuk potongan jargon lainnya dalam judul: bias field. Algoritma iteratif lainnya, seperti VQE, mengambil parameter klasik ke dalam keadaan dan menggunakan optimizer klasik untuk mencari ruang parameter berdimensi banyak untuk menemukan set parameter yang menghasilkan nilai ekspektasi minimum untuk Hamiltonian yang tetap. Dalam kasus ini, mereka malah memvariasikan Hamiltonian setiap saat, bergerak secara adiabatik dari kasus yang diketahui ke kasus yang diminati. Untuk mengubah Hamiltonian, mereka cukup langsung menerapkan nilai ekspektasi Pauli-Z dari satu iterasi sebagai bias field dalam Hamiltonian untuk iterasi berikutnya. Dengan cara ini, mereka mengarahkan dinamika menuju solusi aktual tanpa perlu optimizer klasik."}),"\n",(0,t.jsx)(n.p,{children:"Jadi, mengapa eksperimen ini menarik? Ising spin-glass sangat menarik secara fundamental dalam fisika, tetapi pendekatan baru ini bahkan lebih umum dari itu. Ini bisa diterapkan pada banyak masalah optimasi, sehingga makalah ini menarik secara luas."}),"\n",(0,t.jsx)(n.p,{children:"Dan mengapa kita pikir ini akan berhasil? Algoritma yang mereka usulkan mempercepat evolusi untuk mengurangi kedalaman Circuit, sambil juga menekan transisi non-adiabatik. Lebih lanjut, ini tidak bergantung pada subrutin optimasi klasik apa pun, yang bisa menjadi masalah yang mengarah pada barren plateaus dan terjebak pada minimum lokal. Terakhir, para penulis juga memastikan untuk menyelaraskan interaksi dalam Hamiltonian masalah dengan konektivitas perangkat keras di QPU nyata, yang selalu sangat penting."}),"\n",(0,t.jsx)(n.p,{children:"Jadi, bagaimana metode ini bekerja? Sekali lagi, tidak menggunakan optimizer klasik apa pun, tidak seperti sebagian besar algoritma kuantum iteratif lainnya. Sebaliknya, dengan memasukkan solusi dari setiap iterasi ke input untuk yang berikutnya, algoritma optimasi kuantum bias-field digitized secara bertahap menyempurnakan ground state, membawanya semakin dekat ke keadaan yang berevolusi akhir. Dan dikombinasikan dengan protokol counterdiabatic, kita bisa melakukan ini bahkan dengan Circuit kuantum kedalaman pendek yang seharusnya berjalan lancar di perangkat keras yang berisik."}),"\n",(0,t.jsx)(n.p,{children:"Jadi, ketika eksperimen dilakukan, para penulis memilih untuk menjalankan algoritma pada komputer kuantum IBM 127 qubit Brisbane. Di bawah ini adalah gambar yang menunjukkan iterasi ke-8 dari algoritma optimasi untuk instance spin-glass yang dibangkitkan secara acak, nearest-neighbor pada 100 qubit. Mereka membandingkan hasil simulasi klasik yang ideal dari DCQO dan BF-DCQO, serta hasil eksperimental yang dijalankan pada komputer kuantum. Mereka juga menunjukkan hasil dari solver klasik yang disebut Gurobi sebagai referensi. Hanya dengan 10 iterasi, BF-DCQO memberikan peningkatan drastis dibandingkan DCQO. Meskipun hasil eksperimental sedikit berbeda dari hasil ideal akibat noise, kinerjanya masih lebih baik dari DCQO ideal. Ini menunjukkan bahwa masih ada kemajuan luar biasa yang sedang dibuat terkait optimasi kuantum dan hasil yang baik dilaporkan pada lebih dari 100 qubit untuk pertama kalinya."}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.img,{alt:"Hasil dari makalah Ising spin-glass",src:i(43410).A+"",width:"976",height:"682"})}),"\n",(0,t.jsx)(n.h3,{id:"use-case-3-mrna-secondary-structure-prediction",children:"Kasus Penggunaan 3: Prediksi struktur sekunder mRNA"}),"\n",(0,t.jsxs)(n.p,{children:["Terakhir, kita akan membahas makalah dari Moderna Pharmaceuticals berjudul ",(0,t.jsx)(n.a,{href:"https://arxiv.org/abs/2405.20328",children:"mRNA Secondary Structure Prediction Using Utility-Scale Quantum Computers"}),"."]}),"\n",(0,t.jsx)(n.p,{children:"Pertama, penyegaran singkat tentang mRNA. Messenger RNA adalah jenis RNA yang terlibat dalam sintesis protein. Pada dasarnya membaca instruksi yang diberikan oleh DNA. Struktur sekunder mRNA adalah bagaimana rantai dilipat, seperti yang ditunjukkan dalam diagram di bawah. Dan masalah prediksi struktur sekunder RNA adalah masalah menemukan lipatan paling stabil dari urutan basa atau nukleotida yang membentuk RNA: adenin (A), sitosin (C), urasil (U), dan guanin (G). Gambar di bawah menunjukkan beberapa struktur lipatan umum yang ditemukan dalam mRNA, setiap warna mewakili jenis struktur sekunder yang berbeda. Apa yang membuat satu struktur lebih menguntungkan dari yang lain tidak dipahami dengan baik; semua yang bisa kita lakukan adalah menghitung struktur mana yang menghasilkan energi bebas terendah dibandingkan keadaan yang tidak terlipat. Dan di situlah komputer kuantum masuk."}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.img,{alt:"Diagram struktur sekunder mRNA",src:i(41923).A+"",width:"638",height:"842"})}),"\n",(0,t.jsx)(n.p,{children:"Jadi, mengapa struktur sekunder mRNA penting? Prediksi yang akurat tentangnya sangat penting tidak hanya untuk memahami DNA dan gen kita, tetapi juga untuk merancang terapi berbasis RNA, seperti vaksin COVID-19."}),"\n",(0,t.jsx)(n.p,{children:"Ini sudah lama diketahui sebagai masalah optimasi yang tangguh untuk komputer klasik karena banyaknya kemungkinan konfigurasi. Untuk beberapa konfigurasi, diketahui menjadi masalah NP-complete. Namun, di komputer kuantum, kita bisa memformulasikan prediksi struktur sekunder sebagai masalah optimasi biner \u2013 sesuatu yang kita tahu cara menanganinya. Selanjutnya, sudah ada bukti dalam literatur tentang prediksi RNA yang akurat pada perangkat kuantum skala kecil dan simulator kuantum. Tapi apakah ini akan berhasil pada perangkat keras yang lebih besar?"}),"\n",(0,t.jsx)(n.p,{children:"Eksperimen ini dilakukan menggunakan sesuatu yang disebut conditional value at risk variational quantum eigensolver, yang merupakan modifikasi dari algoritma VQE tradisional dan diharapkan mencapai konvergensi yang lebih baik."}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.img,{alt:"Hasil dari makalah mRNA",src:i(65188).A+"",width:"1158",height:"686"})}),"\n",(0,t.jsx)(n.p,{children:"Plot di atas menunjukkan distribusi probabilitas pengukuran dari bitstring yang diambil sampel, dengan energi yang sesuai untuk instance 42-nukleotida, 80 qubit. Di sini, bitstring melambangkan pasangan nukleotida. Ini mengilustrasikan bahwa bitstring energi terendah yang ditemukan oleh komputer kuantum cocok dengan solver klasik komparatif, jadi itu bagus. Juga ditampilkan adalah struktur terlipat optimal dari rantai nukleotida tersebut berdasarkan bitstring energi terendah yang ditemukan komputer kuantum."}),"\n",(0,t.jsx)(n.h2,{id:"conclusion",children:"Kesimpulan"}),"\n",(0,t.jsx)(n.p,{children:"Semoga tiga kasus penggunaan ini memberimu konteks yang cukup untuk memahami seperti apa pekerjaan mutakhir di bidang ini saat ini, dan kepercayaan diri untuk mencoba eksperimen kuantum baru yang mungkin belum pernah kamu coba sebelumnya."}),"\n",(0,t.jsx)(n.p,{children:"Ingat: komputasi kuantum tidak cocok untuk setiap masalah. Dan ini sebenarnya hanya kesaksian tentang betapa baiknya kita dalam komputasi klasik. Hanya karena kamu pikir bisa menerapkan komputasi kuantum pada suatu masalah tidak berarti itu akan menghasilkan hasil yang menarik; kamu harus mempertimbangkan penskalaan."}),"\n",(0,t.jsx)(n.p,{children:"Kedalaman Circuit adalah pedang bermata dua. Kita perlu itu cukup besar untuk melakukan pekerjaan menarik yang tidak bisa dilakukan komputer klasik, tetapi saat ini, kita tidak bisa meningkatkan kedalaman terlalu banyak karena noise perangkat keras akan menyebabkan fidelitas berkurang. Semuanya tentang menemukan titik manis itu dan mengetahui bahwa itu adalah target yang bergerak. Jadi, luangkan waktu antara sekarang dan pelajaran berikutnya untuk memikirkan masalah yang pernah kamu temui dalam penelitianmu, dan bagaimana kamu mungkin mendekatinya dengan apa yang telah kita pelajari sejauh ini. Dan hei, solusimu mungkin tidak berhasil, dan itu tidak apa-apa. Itulah mengapa ini disebut penelitian."})]})}function d(a={}){const{wrapper:n}={...(0,s.R)(),...a.components};return n?(0,t.jsx)(n,{...a,children:(0,t.jsx)(l,{...a})}):l(a)}},52600(a,n,i){i.d(n,{A:()=>e});const e=i.p+"assets/images/complexity_classes-52979b588e98706373f7abc9b3f5f57c.avif"},77894(a,n,i){i.d(n,{A:()=>e});const e=i.p+"assets/images/hadron_paper-bc9c0a13fc3cd0e44b5c193902ce6dba.avif"},65188(a,n,i){i.d(n,{A:()=>e});const e=i.p+"assets/images/mrna_paper-4b1d694275f2539f69c49bfbb9b5ddd8.avif"},41923(a,n,i){i.d(n,{A:()=>e});const e=i.p+"assets/images/mrna_structure-962f2d5dfb98ac0a2e9c680e23d97ada.avif"},43410(a,n,i){i.d(n,{A:()=>e});const e=i.p+"assets/images/paper_results-aace6d8c4b97868e6cba7fc772e13ad9.avif"},28453(a,n,i){i.d(n,{R:()=>u,x:()=>r});var e=i(96540);const t={},s=e.createContext(t);function u(a){const n=e.useContext(s);return e.useMemo(function(){return"function"==typeof a?a(n):{...n,...a}},[n,a])}function r(a){let n;return n=a.disableParentContext?"function"==typeof a.components?a.components(t):a.components||t:u(a.components),e.createElement(s.Provider,{value:n},a.children)}}}]);